config.command:
set -euo pipefail
cd {{ execution_path }}
python3 .git/todo-batch/bin/scripts/todo-batch/candidates.py --state .git/todo-batch --max 40 --batch-max {{ batch_max }} --size-limits {{ size_ratchet_file }} {{ size_ratchet_root }}

set -euo pipefail
cd {{ execution_path }}
printf '%s' {{ block.triage.output }} > .git/todo-batch/triage.txt
python3 .git/todo-batch/bin/scripts/todo-batch/choose.py --state .git/todo-batch --max {{ batch_max }} --run {{ workflow_run_id }}
